import { useEffect, useState } from 'react'
import { Button } from 'react95'
import styled from 'styled-components'
import { MAPLE_HATCH_PET_URL } from 'constants/mapleHatchPet'
import { useAppWindowRender } from 'utils/zustand/useAppWindowRender'
import AppWindow from '../AppWindow'

const embedMinWidth = 1100

const browserMenuItems = [
  { title: 'File', icon: null },
  { title: 'Edit', icon: null },
  { title: 'View', icon: null },
  { title: 'Favorites', icon: null },
  { title: 'Help', icon: null },
]

function canEmbedMapleHatchPet() {
  return window.innerWidth >= embedMinWidth
}

export default function MapleBrowserWindow() {
  const { onClickWindowClose, windowRenderObj, onClickWindow } = useAppWindowRender()
  const [canEmbed, setCanEmbed] = useState(canEmbedMapleHatchPet)
  const [frameKey, setFrameKey] = useState(0)
  const [loadedFrameKey, setLoadedFrameKey] = useState(-1)
  const isLoading = canEmbed && loadedFrameKey !== frameKey
  let statusText = '외부 브라우저 사용 권장'

  if (canEmbed) {
    statusText = isLoading ? '불러오는 중...' : '완료'
  }

  useEffect(() => {
    const handleResize = () => {
      setCanEmbed(canEmbedMapleHatchPet())
    }

    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  const onClickRefresh = () => {
    if (!canEmbed) return

    setFrameKey(currentFrameKey => currentFrameKey + 1)
  }

  const onClickOpenExternal = () => {
    window.open(MAPLE_HATCH_PET_URL, '_blank', 'noopener,noreferrer')
  }

  return (
    <AppWindow
      width="100vw"
      height="calc(100vh - max(7vh, 54px))"
      top="0"
      left="0"
      zIndex={windowRenderObj.mapleBrowserWindow.zIndexValue}
      onClick={() => onClickWindow('mapleBrowserWindow')}
      fullScreen
    >
      <AppWindow.Header onClick={event => onClickWindowClose('mapleBrowserWindow', event)}>
        Internet Explorer - Maple Hatch Pet
      </AppWindow.Header>
      <BrowserLayout>
        <AppWindow.HeadMenu arr={browserMenuItems} />
        <NavigationBar>
          <NavigationButton type="button" disabled aria-label="뒤로">
            ◀
          </NavigationButton>
          <NavigationButton type="button" disabled aria-label="앞으로">
            ▶
          </NavigationButton>
          <NavigationButton type="button" onClick={onClickRefresh} disabled={!canEmbed} aria-label="새로고침">
            새로고침
          </NavigationButton>
          <AddressLabel htmlFor="maple-browser-address">주소</AddressLabel>
          <AddressInput id="maple-browser-address" value={MAPLE_HATCH_PET_URL} readOnly aria-label="주소" />
          <ExternalButton type="button" onClick={onClickOpenExternal}>
            외부에서 열기
          </ExternalButton>
        </NavigationBar>
        <BrowserViewport>
          {canEmbed ? (
            <>
              <BrowserFrame
                key={frameKey}
                src={MAPLE_HATCH_PET_URL}
                title="Maple Hatch Pet 웹사이트"
                allow="clipboard-write"
                referrerPolicy="strict-origin-when-cross-origin"
                onLoad={() => setLoadedFrameKey(frameKey)}
              />
              {isLoading ? <LoadingOverlay role="status">Maple Hatch Pet을 불러오는 중...</LoadingOverlay> : null}
            </>
          ) : (
            <SmallScreenFallback>
              <FallbackIcon aria-hidden="true">🌐</FallbackIcon>
              <FallbackTitle>넓은 화면에서 열어주세요</FallbackTitle>
              <FallbackDescription>
                이 서비스는 넓은 화면에 최적화되어 있습니다. 화면 폭이 1100px 이상일 때 이 창에서 바로 사용할 수 있습니다.
              </FallbackDescription>
              <Button type="button" onClick={onClickOpenExternal}>
                외부 브라우저에서 열기
              </Button>
            </SmallScreenFallback>
          )}
        </BrowserViewport>
        <StatusBar role="status">
          <StatusText>{statusText}</StatusText>
          <StatusHint>페이지가 보이지 않으면 새로고침하거나 외부에서 열어주세요.</StatusHint>
        </StatusBar>
      </BrowserLayout>
    </AppWindow>
  )
}

const BrowserLayout = styled.div`
  height: calc(100% - 33px);
  min-height: 0;
  display: flex;
  flex-direction: column;
`

const NavigationBar = styled.div`
  padding: 5px;
  display: flex;
  align-items: center;
  gap: 5px;
  border-top: 1px solid #ffffff;
  border-bottom: 1px solid #808080;
  background: #c0c0c0;
`

const NavigationButton = styled(Button)`
  min-width: 34px;
  height: 30px;
  padding: 0 8px;
  white-space: nowrap;
`

const AddressLabel = styled.label`
  padding: 0 3px;
  font-size: 0.82rem;
  white-space: nowrap;
`

const AddressInput = styled.input`
  height: 28px;
  min-width: 0;
  flex: 1;
  padding: 2px 7px;
  box-sizing: border-box;
  border-top: 2px solid #808080;
  border-left: 2px solid #808080;
  border-right: 2px solid #ffffff;
  border-bottom: 2px solid #ffffff;
  background: #ffffff;
  color: #111111;
  font-family: inherit;
  font-size: 0.82rem;
`

const ExternalButton = styled(Button)`
  height: 30px;
  padding: 0 10px;
  white-space: nowrap;
`

const BrowserViewport = styled.div`
  min-height: 0;
  flex: 1;
  position: relative;
  overflow: hidden;
  border-top: 2px solid #808080;
  border-left: 2px solid #808080;
  border-right: 2px solid #ffffff;
  border-bottom: 2px solid #ffffff;
  background: #ffffff;
`

const BrowserFrame = styled.iframe`
  width: 100%;
  min-width: 1024px;
  height: 100%;
  display: block;
  border: 0;
  background: #ffffff;
`

const LoadingOverlay = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  color: #111111;
  font-size: 0.92rem;
`

const SmallScreenFallback = styled.div`
  width: 100%;
  height: 100%;
  padding: 32px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  box-sizing: border-box;
  background: #ffffff;
  color: #1f1f1f;
  text-align: center;
`

const FallbackIcon = styled.span`
  font-size: 2.4rem;
`

const FallbackTitle = styled.h2`
  margin: 0;
  color: #000080;
  font-size: 1.15rem;
`

const FallbackDescription = styled.p`
  max-width: 520px;
  margin: 0;
  line-height: 1.6;
  font-size: 0.9rem;
`

const StatusBar = styled.div`
  min-height: 28px;
  padding: 3px 6px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-sizing: border-box;
  border-top: 1px solid #ffffff;
  background: #c0c0c0;
  color: #1f1f1f;
  font-size: 0.75rem;
`

const StatusText = styled.span`
  min-width: 112px;
  padding: 3px 6px;
  border-top: 1px solid #808080;
  border-left: 1px solid #808080;
  border-right: 1px solid #ffffff;
  border-bottom: 1px solid #ffffff;
`

const StatusHint = styled.span`
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  @media screen and (max-width: 600px) {
    display: none;
  }
`
